// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
contract Child { uint256 public value; constructor(uint256 initial) payable { value = initial; } }
contract Parent { Child public first; constructor(uint256 seed) { first = new Child(seed + 1); } function make(uint256 value, bytes32 salt) external payable returns (address) { Child created = new Child{salt: salt, value: msg.value}(value); return address(created); } }
